-- Pokémon fuyards : Raikou, Entei et Suicune ne se capturent plus par une expédition légendaire,
-- ils changent de zone de Johto chaque heure (rewards.pokemon[0].roaming = 3 % par rencontre).
-- Ciblé : seulement si le Pokémon offert est toujours la bête et n'a pas encore de réglage.
UPDATE "quests" SET "rewards" = jsonb_set("rewards", '{pokemon,0,roaming}', '3'::jsonb)
WHERE ("id", ("rewards"->'pokemon'->0->>'speciesId')) IN (('raikou', '243'), ('entei', '244'), ('suicune', '245'))
  AND ("rewards"->'pokemon'->0->'roaming') IS NULL;--> statement-breakpoint
-- Oiseaux de Galar : trois quêtes de Kanto après Mewtwo, leurs oiseaux sont des fuyards.
INSERT INTO "quests" ("content_version_id", "id", "order", "name", "description", "image", "region_id", "enabled", "unlock", "steps", "rewards")
SELECT v."id", 'artikodin-galar', 5, 'L’oiseau au regard glacial', 'Un oiseau aux ailes violettes, venu d’une région lointaine, plongerait les esprits de Kanto dans la torpeur.', NULL, 'kanto', true, '{"type":"questCompleted","questId":"mewtwo"}'::jsonb, '[{"name":"Ondes étranges","description":"Capture 15 Pokémon Psy.","condition":{"type":"catchPokemon","count":15,"pokemonType":"psychic","speciesId":null}},{"name":"Dans le ciel","description":"Capture 10 Pokémon Vol.","condition":{"type":"catchPokemon","count":10,"pokemonType":"flying","speciesId":null}},{"name":"Sur sa piste","description":"Réussis une expédition sur la Route Victoire avec 2 Pokémon Psy de PE 800 ou plus.","condition":{"type":"expedition","zoneId":"route-victoire","count":1,"memberType":"psychic","memberCount":2,"minMemberPower":800}}]'::jsonb, '{"currency":15000,"items":[{"itemId":"bottle-cap","quantity":1}],"expeditionSlots":0,"daycareSlots":0,"bonuses":[],"pokemon":[{"speciesId":144,"formId":10169,"level":70,"perfectIvs":3,"expedition":{"durationMinutes":240,"minPower":0,"requiredTypes":[],"affinityTypes":["rock","ghost","electric","ice","dark"]},"roaming":3}]}'::jsonb
FROM "content_versions" v
ON CONFLICT DO NOTHING;--> statement-breakpoint
